function typeEggRarity(key){if(typeof MASTER_CHEAT_SPECIES!=='undefined'&&key===MASTER_CHEAT_SPECIES)return'master';if(ELEMENTS[key]?.eggRarity)return ELEMENTS[key].eggRarity;if(ELEMENTS[key]?.secretVariant)return'secret';if(typeof isSecretSpecies==='function'&&isSecretSpecies(key))return'secret';if(ELEMENTS[key]?.masterTier)return'master';if(typeof isExoticSpecies==='function'&&isExoticSpecies(key))return'exotic';return baseTypeEggRarity(key);}
const TYPE_EGG_APEX_PREMIUM={celestial:8000,divine:11000,eternal:15000};const WISHLIST_LIMIT=12;function typeEggApexPrice(key,rank){const premium=TYPE_EGG_APEX_PREMIUM[rank];const base=TYPE_EGG_PRICE[key]||TYPE_EGG_BASE_PRICE[key]||90;return premium?base+premium:base;}
function typeEggRarityBoost(key,rank){if(!TYPE_EGG_APEX_PREMIUM[rank])return 0;const target=RARITY_TIER_ORDER.indexOf(rank);const base=RARITY_TIER_ORDER.indexOf(typeEggRarity(key));return Math.max(0,target-Math.max(0,base));}
const TYPE_EGG_BULK_DEALS=[{size:5,off:0.12},{size:10,off:0.2},];function typeEggAverageApexPrice(rank){const roster=typeof TYPE_EGG_SPECIES!=='undefined'?TYPE_EGG_SPECIES:[];if(!roster.length)return typeEggApexPrice('ember',rank);const total=roster.reduce((sum,key)=>sum+typeEggApexPrice(key,rank),0);return total/roster.length;}
