const TRIBRID_RECIPES=[{parts:['falcon','raven','volt'],name:'Thunder Omen'},{parts:['dragonfly','tide','firefang'],name:'Tidefire Glasswing'},{parts:['honeybee','ladybug','bluebird'],name:'Meadow Chorus'},{parts:['jellyfish','seahorse','pufferfish'],name:'Abyss Lantern'},{parts:['koi','owlet','tortoise'],name:'Pond Sage'},{parts:['firefang','tamer','elk'],name:'Wild Herd'},{parts:['moth','firefly','radiant'],name:'Lantern Swarm'},{parts:['badger','otter','rock'],name:'Stone Burrow'},{parts:['fox','hare','dusk'],name:'Twilight Trickster'},];const TRIBRID_NAMES={};const TRIBRID_BY_KEY={};TRIBRID_RECIPES.forEach(({parts,name})=>{const sorted=[...parts].sort();const key=sorted.join('+');TRIBRID_NAMES[key]=name;TRIBRID_BY_KEY[key]={name,parents:sorted};});function tribridFor(a,b){const complete=(hybrid,plain)=>{if(!hybrid?.hybridParents||hybrid.hybridParents.length!==2)return null;if(plain?.hybridParents)return null;const parts=[...hybrid.hybridParents,plain.element];if(new Set(parts).size!==3)return null;return TRIBRID_BY_KEY[[...parts].sort().join('+')]||null;};return complete(a,b)||complete(b,a);}
