const HERO_SPECIES=[];const HERO_BY_ROLE={hero:[],villain:[],anti:[]};HERO_WAVE_DEFS.forEach(([roleKey,key,name,primary,light,deep,accent,motifKey,partner,hybrid,home],index)=>{const role=HERO_ROLE_META[roleKey];const motif=HERO_MOTIF_META[motifKey];if(!role||!motif||ELEMENTS[key])return;ELEMENTS[key]={name,primary,light,deep,accent,trait:motif.trait,blurb:`${role.blurb} ${motif.blurb}`,greeting:role.greetings[index%role.greetings.length],likes:role.likes,heroRole:roleKey,heroMotif:motifKey,heroPublisher:heroPublisherFor(key),};GENE_POWERS[key]={name:motif.gene,icon:motif.icon,desc:motif.desc,effect:motif.effect};TITAN_NAMES[key]=`${name} Titan`;TYPE_EGG_BASE_PRICE[key]=role.price;TYPE_EGG_PRICE[key]=discountedEggPrice(role.price);if(ELEMENTS[partner])HYBRID_NAMES[pairKey(key,partner)]=hybrid;NAME_START[key]=[name.replace(/^The /,'').split(' ')[0],...name.split(' ').slice(1,3)];const homes=[home,...role.homes];homes.forEach((scene)=>{if(SCENES[scene]&&!SCENES[scene].species.includes(key))SCENES[scene].species.push(key);});HERO_SPECIES.push(key);HERO_BY_ROLE[roleKey].push(key);});ELEMENT_KEYS.push(...HERO_SPECIES);['spiderman'].forEach((key)=>{if(!ELEMENTS[key])return;ELEMENTS[key].heroPublisher='marvel';ELEMENTS[key].heroRole='hero';});
