const VAULT_MONTHLY_KEYS=VAULT_MONTH_DEFS.map((def)=>def[0]);const VAULT_MONTH_EXTRA_KEYS=VAULT_MONTH_EXTRA_DEFS.map((def)=>def[0]);const VAULT_WEEKLY_KEYS=VAULT_WEEK_DEFS.map((def)=>def[0]);const VAULT_ROTATION_KEYS=[...VAULT_MONTHLY_KEYS,...VAULT_MONTH_EXTRA_KEYS,...VAULT_WEEKLY_KEYS];function vaultCalendar(date=new Date()){const yearStart=new Date(date.getFullYear(),0,1);const weekNumber=Math.floor((date-yearStart)/604800000);const day=date.getDay();const slot=day===0||day>=4?1:0;const base=((weekNumber*2)%VAULT_WEEKLY_KEYS.length+VAULT_WEEKLY_KEYS.length)%VAULT_WEEKLY_KEYS.length;return{date,month:date.getMonth(),monthName:VAULT_MONTH_NAMES[date.getMonth()],weekNumber,slot,base,slotWindow:slot===0?'Monday–Wednesday':'Thursday–Sunday',activeCycle:slot===0?base:(base+1)%VAULT_WEEKLY_KEYS.length,};}
function vaultOpen(key,date=new Date()){const meta=typeof SECRET_SPECIES_META!=='undefined'?SECRET_SPECIES_META[key]:null;if(!meta||!meta.vaultWindow)return false;const cal=vaultCalendar(date);if(meta.vaultWindow.kind==='month')return meta.vaultWindow.month===cal.month;if(meta.vaultWindow.kind==='week')return meta.vaultWindow.cycle===cal.activeCycle;return false;}
function vaultNextRelay(cal,key){const total=VAULT_WEEKLY_KEYS.length;const offset=(VAULT_WEEKLY_KEYS.indexOf(key)-cal.base+total)%total;const weeks=cal.slot===1&&offset===0?total/2:Math.floor(offset/2);return{weeks,day:offset%2===0?'Monday':'Thursday'};}
function vaultWindowLabel(key,date=new Date()){const meta=typeof SECRET_SPECIES_META!=='undefined'?SECRET_SPECIES_META[key]:null;if(!meta||!meta.vaultWindow)return'Progress secret';const cal=vaultCalendar(date);if(meta.vaultWindow.kind==='month'){const month=VAULT_MONTH_NAMES[meta.vaultWindow.month];if(vaultOpen(key,date)){const lastDay=new Date(date.getFullYear(),cal.month+1,0).getDate();return `Open now · closes ${lastDay} ${month.slice(0, 3)}`;}
const year=meta.vaultWindow.month<cal.month?date.getFullYear()+1:date.getFullYear();return `Opens 1 ${month.slice(0, 3)} ${year}`;}
if(vaultOpen(key,date))return `Open now · ${cal.slotWindow} window`;const next=vaultNextRelay(cal,key);const when=next.weeks===0?`this ${next.day}`:next.weeks===1?`next ${next.day}`:`in ${next.weeks} weeks (${next.day})`;return `Opens ${when} · ${meta.name}`;}
function currentVaultKeys(date=new Date()){const cal=vaultCalendar(date);return{calendar:cal,open:[VAULT_MONTHLY_KEYS[cal.month],VAULT_MONTH_EXTRA_KEYS[cal.month],VAULT_WEEKLY_KEYS[cal.activeCycle]].filter(Boolean),label:`${cal.monthName} monthly keepers · ${cal.slotWindow} relay`,};}
