function gtaGameLabel(key){const meta=ELEMENTS[key];if(!meta||!meta.gta)return'';const group=GTA_GROUPS[meta.gtaGroup];return group?`${meta.gtaGame} · ${group.label}`:meta.gtaGame||'GTA';}
