const BIOME_QUEST_DEFS={'gta-libertycity':{title:'Dockside Debts',icon:'🗽',steps:[['Walk the rain-slick docks','travel',1,60,0],['Win 2 games under the neon','game',2,110,40],['Care for a sprite dockside twice','care',2,220,80],],},'gta-vicecity':{title:'Sunset Radio',icon:'🌴',steps:[['Watch the sun drop over Vice Beach','travel',1,60,0],['Win 2 games to that synth station','game',2,110,40],['Share a snack with a sprite twice','care',2,220,80],],},'gta-sanandreas':{title:'Backroad Mile',icon:'🌵',steps:[['Ride out to the backroads','travel',1,60,0],['Win 2 games in the dust','game',2,110,40],['Patch a sprite up twice','care',2,220,80],],},'gta-losantos':{title:'Hillside Signal',icon:'🌇',steps:[['Take the hillside overlook','travel',1,60,0],['Win 2 games above the city','game',2,110,40],['Bathe a sprite twice after the smog','care',2,220,80],],},'gta-london':{title:'Fog on the Cobbles',icon:'☂️',steps:[['Step out into the fog','travel',1,60,0],['Win 2 games in the wet','game',2,110,40],['Rub a sprite warm twice','care',2,220,80],],},'gta-chinatown':{title:'Lantern Ledger',icon:'🏮',steps:[['Slip into the lantern alleys','travel',1,60,0],['Win 2 games in the back rooms','game',2,110,40],['Feed a sprite twice from the market','care',2,220,80],],},'gta-anywhere':{title:'Retro Grid Run',icon:'🚧',steps:[['Ride the retro grid','travel',1,60,0],['Win 2 games in the future-past','game',2,110,40],['Clean up a sprite twice','care',2,220,80],],},'exotic-backstage':{title:'Soundcheck',icon:'🎧',steps:[['Get behind the stage','travel',1,60,0],['Win 2 games to the monitors','game',2,110,40],['Hype a sprite up twice','care',2,220,80],],},'exotic-supernova':{title:'Red Carpet Comet',icon:'🌟',steps:[['Walk the starlight carpet','travel',1,60,0],['Win 2 games on the comet','game',2,110,40],['Feed a sprite twice before the gala','care',2,220,80],],},'exotic-jester':{title:'Card Trick',icon:'🃏',steps:[['Follow the crooked lane','travel',1,60,0],['Win 2 games in the mirror maze','game',2,110,40],['Cheer a sprite up twice','care',2,220,80],],},'exotic-litlair':{title:'Velvet Rope',icon:'🔥',steps:[['Get past the velvet rope','travel',1,60,0],['Win 2 games in the lounge','game',2,110,40],['Bathe a sprite twice before the show','care',2,220,80],],},'exotic-rift':{title:'Storm Ring',icon:'👑',steps:[['Enter the storm ring','travel',1,60,0],['Win 2 games inside the arena','game',2,110,40],['Patch a sprite up twice','care',2,220,80],],},'exotic-grandslam':{title:'Title Night',icon:'🏆',steps:[['Walk into the coliseum','travel',1,60,0],['Win 2 games under the lights','game',2,110,40],['Rub a sprite down twice','care',2,220,80],],},};const BIOME_QUESTS={};Object.entries(BIOME_QUEST_DEFS).forEach(([sceneKey,def])=>{if(!SCENES[sceneKey])return;BIOME_QUESTS[sceneKey]={scene:sceneKey,title:def.title,icon:def.icon,steps:def.steps.map(([text,kind,,coins,xp],index)=>({text:text.replace(/\b2 games\b/g,'1 game').replace(/\btwice\b/g,'once'),kind,need:1,reward:{coins,xp,bond:index===2?8:2},})),};});const BIOME_QUEST_KEYS=Object.keys(BIOME_QUESTS);function biomeQuestState(sceneKey){const q=state.biomeQuests&&state.biomeQuests[sceneKey];return q&&typeof q==='object'?q:{step:0,progress:0,done:false};}
function biomeQuestStep(sceneKey){const def=BIOME_QUESTS[sceneKey];if(!def)return null;const q=biomeQuestState(sceneKey);if(q.done)return null;const step=def.steps[q.step];return step?{def,q,step,index:q.step}:null;}
function biomeQuestProgress(sceneKey){const info=biomeQuestStep(sceneKey);if(!info)return{done:true,have:0,need:0};return{done:false,have:Math.min(info.step.need,Math.max(0,Number(info.q.progress)||0)),need:info.step.need,};}
;
const GUARDIAN_ROAMING=[];const GUARDIAN_POOLS={};(function buildGuardianPools(){if(typeof SCENE_KEYS==='undefined'||typeof ELEMENT_KEYS==='undefined')return;const byHome={};ELEMENT_KEYS.forEach((key)=>{const element=ELEMENTS[key];if(!element||!element.gtaHome||!SCENES[element.gtaHome])return;if(!byHome[element.gtaHome])byHome[element.gtaHome]=[];byHome[element.gtaHome].push(key);});const roam=[];const addRoam=(key)=>{if(key&&ELEMENTS[key]&&!roam.includes(key))roam.push(key);};Object.values(SCENES).forEach((scene)=>{if(scene&&scene.exoticBiome&&scene.guardian)addRoam(scene.guardian);});(typeof GTA_BIOME_KEYS!=='undefined'?GTA_BIOME_KEYS:[]).forEach((key)=>{if(byHome[key]&&byHome[key][0])addRoam(byHome[key][0]);});for(let i=0;i<ELEMENT_KEYS.length;i+=97)addRoam(ELEMENT_KEYS[i]);GUARDIAN_ROAMING.push(...roam);SCENE_KEYS.forEach((sceneKey)=>{const scene=SCENES[sceneKey];if(!scene)return;const pool=[];const add=(key)=>{if(key&&ELEMENTS[key]&&!pool.includes(key))pool.push(key);};(scene.species||[]).forEach(add);(byHome[sceneKey]||[]).forEach(add);if(scene.guardian)add(scene.guardian);roam.forEach(add);GUARDIAN_POOLS[sceneKey]=pool;});})();function guardianPoolForScene(sceneKey){return GUARDIAN_POOLS[sceneKey]||GUARDIAN_ROAMING;}
function guardianPick(sceneKey,index=0){const pool=guardianPoolForScene(sceneKey);if(!pool.length)return null;const size=pool.length;const safe=((Math.round(Number(index)||0)%size)+size)%size;return pool[safe];}
function guardianTotalForScene(sceneKey){return guardianPoolForScene(sceneKey).length;}
;
const CUSTOM_GUARDIANS=[{key:'cg_wardenhart',name:'Warden Hart',wins:2,icon:'🦌',palette:['#d9a441','#fff3c4','#5c3a0a','#8be9ff'],trait:'Patient — counts every challenger and remembers the good ones.',blurb:'The first guardian to join you: a soft-antlered warden with a lantern for a heart.',greeting:'You came back. Good. Let us see what you learned.',gene:['Warden Ward','🛡️','+12% bond from practice bouts and needs fade 8% slower.',{bond:1.12,decay:0.92}],},{key:'cg_embermaw',name:'Ember Maw',wins:4,icon:'🐉',palette:['#ff7a4d','#ffe0d0','#5a1f08','#ffd166'],trait:'Furnace-hearted — warms the whole arena without asking.',blurb:'A compact dragon that guards the forge district and considers every duel a friendly barbecue.',greeting:'Stand closer. You look cold. That is the point of me.',gene:['Forge Breath','🔥','Practice bouts pay +2 coins and +10% XP.',{gameCoins:2,xp:1.1}],},{key:'cg_tidekeeper',name:'Tide Keeper',wins:7,icon:'🌊',palette:['#4db8d8','#c2f0ff','#0f4d66','#6fffe0'],trait:'Tidal — keeps every promise on the same schedule as the sea.',blurb:'A calm guardian who steps out of the shallows only when the Hollow has earned a little patience.',greeting:'The tide brought you. It usually knows what it is doing.',gene:['Low Tide','🌊','Gifts arrive 15% sooner and energy fades 15% slower.',{giftSpeed:1.15,energyDecay:0.85}],},{key:'cg_thornwarden',name:'Thorn Warden',wins:11,icon:'🌿',palette:['#8fe07a','#efffdc','#2f5a1a','#ff9ec7'],trait:'Rooted — has never once lost the same duel twice.',blurb:'A garden guardian grown from eleven good bouts and one very stubborn hedge.',greeting:'Eleven doors. The garden heard every one of them.',gene:['Briar Guard','🌿','+15% XP and pets build 20% more bond.',{xp:1.15,petBond:1.2}],},{key:'cg_starregent',name:'Star Regent',wins:16,icon:'⭐',palette:['#c9a6ff','#e9ddff','#5b3b8a','#7affd8'],trait:'Regal — rules an empty court and keeps it spotless.',blurb:'A prism-feathered regent who keeps the Hollow’s night ledger and duels only after dark.',greeting:'Sixteen victories. The court recognises you. Do not let it go to your head.',gene:['Night Ledger','🌙','Night games pay +4 coins and +15% XP.',{nightCoins:4,xp:1.15}],},{key:'cg_hollowmaw',name:'Hollow Maw',wins:22,icon:'🕳️',palette:['#5a5668','#b8b4c8','#22202c','#ff8ad8'],trait:'Quiet — swallows sound and gives it back as a better idea.',blurb:'The Hollow’s own guardian: a shadow with bright eyes that only shows up once you are truly known.',greeting:'You have been busy. I have been watching. Shall we?',gene:['Quiet Echo','🕳️','Needs fade 15% slower and all games pay +3 coins.',{decay:0.85,gameCoins:3}],},{key:'cg_goldcrown',name:'Gold Crown',wins:30,icon:'👑',palette:['#e8c46a','#fff6d6','#7a5a14','#8be9ff'],trait:'Undefeated — until someone better walks in, which is the fun part.',blurb:'A champion guardian who treats every practice bout like a title match.',greeting:'Thirty. The crown is heavy. You may try to take it.',gene:['Champion’s Purse','👑','Games pay +6 coins and duel wins give +25% bond.',{gameCoins:6,bond:1.25}],},{key:'cg_aurorawing',name:'Aurora Wing',wins:40,icon:'🌌',palette:['#8be9ff','#e6fbff','#123a4a','#b69cff'],trait:'Skybound — arrives only when the Hollow has made a name for itself.',blurb:'The final earned guardian: a wide-winged keeper of lights who guards every biome at once.',greeting:'Forty guardians bested. The sky has been waiting to meet you.',gene:['Sky Writ','🌌','+20% XP, gifts 20% sooner, and needs fade 10% slower.',{xp:1.2,giftSpeed:1.2,decay:0.9}],},];function customGuardianDef(key){return CUSTOM_GUARDIANS.find((guardian)=>guardian.key===key)||null;}
function customGuardianUnlocksFor(wins){const count=Math.max(0,Number(wins)||0);return CUSTOM_GUARDIANS.filter((guardian)=>count>=guardian.wins).map((guardian)=>guardian.key);}
function installCustomGuardianSpecies(key){const def=customGuardianDef(key);if(!def||typeof ELEMENTS==='undefined')return null;if(ELEMENTS[key])return ELEMENTS[key];const[primary,light,deep,accent]=def.palette;ELEMENTS[key]={name:def.name,primary,light,deep,accent,trait:def.trait,blurb:def.blurb,greeting:def.greeting,likes:'Star Pop',guardianOnly:true,customGuardian:true,};if(typeof GENE_POWERS!=='undefined'){const gene=def.gene;GENE_POWERS[key]={name:gene[0],icon:gene[1],desc:gene[2],effect:gene[3]};}
if(typeof TITAN_NAMES!=='undefined')TITAN_NAMES[key]=`${def.name} Titan`;if(typeof NAME_START!=='undefined')NAME_START[key]=[def.name.split(' ')[0],'Guardian','Warden','Keeper'];if(typeof TYPE_EGG_BASE_PRICE!=='undefined')TYPE_EGG_BASE_PRICE[key]=500;return ELEMENTS[key];}
function syncCustomGuardians(list){const keys=Array.isArray(list)?list:[];CUSTOM_GUARDIANS.forEach((guardian)=>installCustomGuardianSpecies(guardian.key));if(typeof GUARDIAN_ROAMING==='undefined'||typeof GUARDIAN_POOLS==='undefined')return;keys.forEach((key)=>{if(!customGuardianDef(key)||!ELEMENTS[key])return;if(!GUARDIAN_ROAMING.includes(key))GUARDIAN_ROAMING.push(key);Object.keys(GUARDIAN_POOLS).forEach((sceneKey)=>{if(!GUARDIAN_POOLS[sceneKey].includes(key))GUARDIAN_POOLS[sceneKey].push(key);});});}
CUSTOM_GUARDIANS.forEach((guardian)=>installCustomGuardianSpecies(guardian.key));
