const DAILY_EGG_GIFT={name:'Daily Egg Gift',icon:'🥚',blurb:'Every day the Hollow leaves one wrapped egg on the doorstep, and you choose the sprite inside.',};function dailyEggPool(){return ELEMENT_KEYS.filter((key)=>ELEMENTS[key]&&!isSecretSpecies(key));}
