if(variant===3){return `<path d="M60 29l6 6-6 6-6-6Z" fill="${c.accent}" opacity=".65" stroke="${c.deep}" stroke-width=".8"/><path d="M35 79c4-2 7-2 10 0M75 79c3-2 6-2 10 0" stroke="${c.light}" stroke-width="1.3" fill="none" opacity=".45"/>`;}
if(variant===4){return `<path d="M44 57c3 2 5 2 8 0M68 57c3 2 5 2 8 0" stroke="${c.deep}" stroke-width="1.7" fill="none" stroke-linecap="round" opacity=".45"/><path d="M51 90c6-3 12-3 18 0" stroke="${c.light}" stroke-width="1.5" fill="none" stroke-linecap="round" opacity=".55"/><circle cx="35" cy="49" r="2" fill="${c.accent}" opacity=".6"/>`;}
if(variant===5){return `<path d="M43 67h34M49 75h22" stroke="${c.light}" stroke-width="1.5" fill="none" opacity=".5"/><path d="M60 57l4.5 4.5-4.5 4.5-4.5-4.5Z" fill="${c.accent}" opacity=".6" stroke="${c.deep}" stroke-width=".7"/><circle cx="81" cy="45" r="2.3" fill="${c.light}" opacity=".6"/>`;}
