var STAGE_ORDER=['baby','juvenile','sprite','youngadult','midadult','highadult','elder','ancient','sensei','apex','omni','celestial'];const STAGE_LABELS={baby:'Baby',juvenile:'Juvenile',sprite:'Teen',youngadult:'Young Adult',midadult:'Mid-Adult',highadult:'High Adult',elder:'Elderly',ancient:'Ancient',sensei:'Sensei',apex:'Apex Cosmic',omni:'Omni Immortal',celestial:'Celestial Mythic'};const STAGE_LEVEL={baby:1,juvenile:5,sprite:10,youngadult:18,midadult:25,highadult:35,elder:100,ancient:500,sensei:1000,apex:2500,omni:5000,celestial:10000};const GROWTH_MILESTONES=[5,10,18,25,35,100,250,500,1000,2500,5000,10000];function stageEvolutionInfo(s){if(!s||s.stage==='egg')return{egg:true,current:'egg',next:null,nextLabel:'Egg',required:1,levelsLeft:0,ready:false,final:false,progress:0};const index=STAGE_ORDER.indexOf(s.stage);const next=index>=0&&index<STAGE_ORDER.length-1?STAGE_ORDER[index+1]:null;if(!next)return{egg:false,current:s.stage,next:null,nextLabel:'Final stage',required:MAX_LEVEL,levelsLeft:Math.max(0,MAX_LEVEL-s.level),ready:false,final:true,progress:s.level>=MAX_LEVEL?1:Math.min(1,(s.xp||0)/xpNeeded(s.level))};const required=STAGE_LEVEL[next];const start=STAGE_LEVEL[s.stage]||1;const xpPart=s.level>=required?0:Math.min(1,(s.xp||0)/xpNeeded(s.level));const raw=required>start?(s.level-start+xpPart)/(required-start):1;return{egg:false,current:s.stage,next,nextLabel:STAGE_LABELS[next]||next,required,levelsLeft:Math.max(0,required-s.level),ready:s.level>=required,final:false,progress:Math.max(0,Math.min(1,raw))};}
function moodOf(s){if(!s)return{key:'content',label:'Content',icon:'🙂'};if(s.stage==='egg')return{key:'egg',label:'Cracking',icon:'🥚'};if(s.asleep)return{key:'sleep',label:'Dreaming',icon:'😴'};const n=s.needs;const avg=(n.hunger+n.energy+n.joy+n.clean)/4;if(n.hunger<14)return{key:'starving',label:'Starving',icon:'🍽️'};if(n.clean<14)return{key:'filthy',label:'Grubby',icon:'🫧'};if(n.energy<14)return{key:'exhausted',label:'Sleepy',icon:'💤'};if(avg>=92&&s.bond>=55)return{key:'pampered',label:'Pampered',icon:'🛁'};if(n.joy>=93&&avg>=60)return{key:'giddy',label:'Giddy',icon:'🤩'};if(typeof warmScore==='function'&&warmScore(s)>=2&&avg>=55)return{key:'cozy',label:'Cozy',icon:'🧣'};if(s.bond<=18&&avg>=55)return{key:'lonely',label:'Lonely',icon:'🫥'};if(n.hunger<35)return{key:'peckish',label:'Peckish',icon:'🍪'};if(n.clean<35)return{key:'muddy',label:'Muddy',icon:'🐾'};if(s.bond>=85&&avg>=66)return{key:'bonded',label:'Bonded',icon:'💖'};if(avg>=78)return{key:'radiant',label:'Radiant',icon:'✨'};if(avg>=62)return{key:'happy',label:'Happy',icon:'😊'};if(avg>=45)return{key:'content',label:'Content',icon:'🙂'};if(avg>=30)return{key:'restless',label:'Restless',icon:'😕'};return{key:'grumpy',label:'Grumpy',icon:'😾'};}
function bondTier(s){return bondRankFor(s?.bond||0).name;}
function spriteSubtitle(s){if(!s)return'';if(s.stage==='egg')return s.hatch>=100?'Ready to hatch':'Warm it with taps';const base=formName(s)||typeName(s);const finish=finishOf(s)?`${finishOf(s).name} · `:'';return `${s.shiny ? '✨ Shiny · ' : ''}${finish}${base} · ${BREEDS[s.breed]?.name || 'Puff'} · Gen ${(s.gen || 0) + 1}`;}
function restLeft(s){return Math.max(0,(s.restUntil||0)-Date.now());}
function isBedtime(d=new Date()){return timePhase(d).key==='night';}
function sleepInfo(s){if(!s||!s.asleep)return null;const now=Date.now();const end=s.sleepUntil||now;const start=s.sleepStart||Math.max(0,end-NAP_MS);const total=Math.max(1000,end-start);const elapsed=clamp(now-start,0,total);const cycles=Math.max(1,s.sleepCycles||1);const cycleLen=total/cycles;const cycle=Math.min(cycles,Math.floor(elapsed/cycleLen)+1);return{cycles,cycle,progress:elapsed/total,cycleProgress:cycleLen>0?(elapsed%cycleLen)/cycleLen:0,left:Math.max(0,end-now),total,};}
