function rollGender(){const r=Math.random();return r<0.46?'female':r<0.92?'male':'neutral';}
function genderOf(s){return GENDERS[s&&s.gender]?GENDERS[s.gender]:GENDERS.neutral;}
function genderFromId(id){const text=String(id||'sprite');let hash=0;for(let i=0;i<text.length;i++)hash=(hash*31+text.charCodeAt(i))%99991;const roll=hash%100;return roll<46?'female':roll<92?'male':'neutral';}
function rollSize(){const r=Math.random();return r<0.28?'small':r<0.8?'standard':'large';}
function specialCombo(s){return s?.special?COMBOS.find((c)=>c.id===s.special)||null:null;}
function gameCoinBase(baseCoins=0){const score=Math.max(0,Number(baseCoins)||0);return Math.min(GAME_COIN_BASE_CAP,GAME_COIN_BASE+score*GAME_COIN_SCORE_VALUE);}
function gameCoinPayout(baseCoins=0){const s=activeSprite();let payout=gameCoinBase(baseCoins);let effectCoins=0;if(s){const fx=spriteEffects(s);effectCoins=fx.gameCoins||0;const phase=timePhase().key;if(phase==='night')effectCoins+=fx.nightCoins||0;if(phase==='day')effectCoins+=fx.dayCoins||0;}
const rarityBonus=s?spriteRarityBonus(s):0;const holiday=typeof holidayCoinMult==='function'?holidayCoinMult():1;const weekly=weeklyEventCoinMult();const outfit=typeof fashionSeasonMod==='function'?fashionSeasonMod('gameCoins'):1;payout=Math.round((payout+effectCoins+rarityBonus)*holiday*weekly*outfit);payout=Math.min(GAME_COIN_CAP,Math.max(0,payout));return{payout,effectCoins,rarityBonus,holiday,weekly,outfit};}
