function formOf(s){return s?.form?EVOLUTION_FORMS[s.form]||null:null;}
function formName(s){const form=formOf(s);if(!form)return null;if(form.id==='titan')return TITAN_NAMES[s.element]||form.label;return `${(ELEMENTS[s.element] || ELEMENTS.bloom).name} ${form.label}`;}
function spriteEffects(s){if(!s)return{};const merged={};const add=(effect={})=>{Object.entries(effect).forEach(([key,value])=>{if(['gameCoins','petCoins','chatCoins','nightCoins','dayCoins','checkinCoins','taskCoins'].includes(key)){merged[key]=(merged[key]||0)+value;}else if(['xp','petBond','giftSpeed','decay','joyDecay','hungerDecay','energyDecay','cleanDecay','snackXp'].includes(key)){merged[key]=(merged[key]||1)*value;}else{merged[key]=value;}});};add(GENE_POWERS[s.element]?.effect);add(typeof abilityEffectsFor==='function'?abilityEffectsFor(s):{});add(HABITS[s.breed]?.effect);add(FINISHES[s.variant]?.effect);add(specialCombo(s)?.power.effect);add(formOf(s)?.power.effect);add(bondRankFor(s?.bond||0).effect);add(typeof window.spriteTraitMods==='function'?window.spriteTraitMods(s):null);if(['common','uncommon'].includes(spriteRarityKey(s))){merged.giftSpeed=(merged.giftSpeed||1)*1.25;}
const rebirths=Math.max(0,Number(s.rebirths)||0);if(rebirths){merged.xp=(merged.xp||1)*(1+0.08*rebirths);merged.gameCoins=(merged.gameCoins||0)+rebirths;merged.giftSpeed=(merged.giftSpeed||1)*(1+0.03*rebirths);}
return merged;}
function habitatFor(s,sceneKey=state.theme.scene){const scene=SCENES[sceneKey]||SCENES.grove;const match=!!s&&(scene.allSprites||(scene.species||[]).includes(s.element));const bonus=match?(scene.bonus||0.4):0.1;return{scene,match,bonus,percent:Math.round(bonus*100)};}
function spritePowers(s){const list=[{kind:'Gene',...(GENE_POWERS[s.element]||{})},{kind:'Habit',...(HABITS[s.breed]||{})},];const combo=specialCombo(s);if(combo)list.push({kind:'Combo',...combo.power});const form=formOf(s);if(form)list.push({kind:'Evolution',...form.power});const finish=finishOf(s);if(finish)list.push({kind:'Finish',name:`${finish.name} finish`,icon:finish.icon,desc:finish.bonus});return list;}
function dietInfo(s){return Object.keys(DIET_PATHS).map((key)=>({key,...DIET_PATHS[key],points:Math.max(0,s?.diet?.[key]||0),need:EVOLUTION_AFFINITY,ready:(s?.diet?.[key]||0)>=EVOLUTION_AFFINITY,}));}
function cuisineInfo(s){return Object.keys(CUISINE_PATHS).map((key)=>({key,...CUISINE_PATHS[key],points:Math.max(0,Number(s?.cuisine?.[key])||0),need:EVOLUTION_AFFINITY,ready:(Number(s?.cuisine?.[key])||0)>=EVOLUTION_AFFINITY,}));}
function catchFoodSickness(s,food){if(!s||!food||typeof Sickness==='undefined'||typeof Sickness.foodCheck!=='function')return null;const illness=Sickness.foodCheck(s,food);if(!illness)return null;const info=typeof ILLNESSES!=='undefined'?ILLNESSES[illness.key]:null;toast(`${displayName(s)} has ${info ? `${info.icon} ${info.name}` : 'a poorly tummy'} after ${food.name}.`,info?info.icon:'🤒');return illness;}
function isFavoriteFood(s,foodId){const traits=typeof BREED_TRAITS!=='undefined'?BREED_TRAITS[s?.breed]:null;const formFavorite=s?.form?EVOLUTION_FORMS[s.form]?.favorite:null;return!!((traits&&traits.favorite===foodId)||formFavorite===foodId);}
function dietGainRaw(s,foodId,bonus=0){const diet=FOOD_DIET[foodId];if(!s||!diet)return null;s.diet=s.diet||{};const before=s.diet[diet.path]||0;const gain=Math.max(1,Number(diet.gain)||1)+bonus;s.diet[diet.path]=before+gain;return{path:diet.path,before,after:s.diet[diet.path],gain};}
