function announceEvolutionReady(s,diet,cuisine){if(!s||s.form||s.level<EVOLUTION_LEVEL)return;const dietReady=diet&&diet.before<EVOLUTION_AFFINITY&&diet.after>=EVOLUTION_AFFINITY;const cuisineReady=cuisine&&cuisine.before<EVOLUTION_AFFINITY&&cuisine.after>=EVOLUTION_AFFINITY;if(dietReady||cuisineReady)toast(`${displayName(s)} is ready to evolve! Check their details.`,'🧬');}
function snackCount(key){return Math.max(0,Number(state.inventory?.snacks?.[key])||0);}
function snackTotal(){return SNACK_KEYS.reduce((n,key)=>n+snackCount(key),0);}
function addSnackRaw(key,count=1){if(!SNACKS[key])return 0;state.inventory=state.inventory||{snacks:{},foods:{}};state.inventory.snacks=state.inventory.snacks||{};state.inventory.snacks[key]=Math.max(0,(state.inventory.snacks[key]||0)+count);return state.inventory.snacks[key];}
