function foodTotal(){return FOOD_KEYS.reduce((n,key)=>n+foodCount(key),0);}
function unlockedFoodKeys(){return FOOD_KEYS.filter((k)=>!FOODS[k].giftOnly&&(!FOODS[k].monthly||(state.foodUnlocks||[]).includes(k))&&!(typeof cafeFoodLocked==='function'&&cafeFoodLocked(k)));}
function candyMorphRaw(s,itemKey){if(!s||s.stage==='egg'||typeof CANDY_ITEMS==='undefined'||!CANDY_ITEMS.includes(itemKey))return null;s.sugar=(Number(s.sugar)||0)+1;if(s.sugar<3)return null;s.sugar=0;const choices=CANDY_SPECIES.filter((key)=>key!==s.element);if(!choices.length)return null;s.element=pick(choices);s.hybrid=null;s.hybridParents=null;state.stats.candyMorphs=(state.stats.candyMorphs||0)+1;toast(`${displayName(s)} transformed into ${ELEMENTS[s.element].name}!`,'🍬');return s.element;}
function addFoodRaw(key,count=1){if(!FOODS[key])return 0;state.inventory=state.inventory||{snacks:{},foods:{}};state.inventory.foods=state.inventory.foods||{};state.inventory.foods[key]=Math.max(0,(state.inventory.foods[key]||0)+count);return state.inventory.foods[key];}
function scheduleGiftRaw(first=false){if(!state.started)return;const candidates=grownSprites();if(!candidates.length){state.gift=null;return;}
const sprite=activeSprite()||pick(candidates);const speed=(spriteEffects(sprite).giftSpeed||1)*(typeof holidayGiftSpeed==='function'?holidayGiftSpeed():1)*weeklyEventGiftSpeed();const seconds=(first?rand(45,110):rand(150,360))/speed;state.gift={spriteId:sprite.id,createdAt:Date.now(),readyAt:Date.now()+seconds*1000,notified:false,};}
