function randomWildRaw({rare=false,mythic=false}={}){const stage=mythic?'elder':pick(rare?['juvenile','sprite','youngadult','midadult','highadult','elder']:['baby','juvenile','sprite','youngadult','midadult','highadult','elder']);const level={baby:randInt(1,4),juvenile:randInt(5,9),sprite:randInt(10,17),youngadult:randInt(18,24),midadult:randInt(25,34),highadult:randInt(35,99),elder:randInt(100,149),}[stage];const combo=rare&&chance(0.55)?pick(COMBOS):null;const mutation=chance(rare?0.5:0.08)?pick(MUTATIONS):null;const variant=rollFinish(rare?0.4:0.12);const element=(window.wildSpeciesRoll?window.wildSpeciesRoll():pick(WILD_SPECIES));const size=mythic||(rare&&chance(0.55))?'large':rollSize();const sprite=makeSprite({element,breed:defaultBreedFor(element),palette:combo?combo.palette:mutation?mutation.palette:chance(0.3)?pick(PALETTE_KEYS.filter((k)=>k!=='native')):'native',pattern:combo?combo.pattern:pick(PATTERN_KEYS),accessory:combo?combo.accessory:chance(0.3)?pick(FREE_ACCESSORY_KEYS):'none',personality:pick(PERSONALITY_KEYS),mutation:mutation?mutation.name:null,variant,special:combo?combo.id:null,stage,level,size,form:mythic?pick(Object.keys(EVOLUTION_FORMS)):null,gen:randInt(0,3),bond:randInt(8,34),needs:{hunger:randInt(70,96),energy:randInt(70,96),joy:randInt(72,98),clean:randInt(76,100)},hatch:100,});sprite.name=makeName(element);state.sprites.push(sprite);if(!state.activeId)state.activeId=sprite.id;return sprite;}
