function ensureDaily(){const today=dayKey();if(state.daily&&state.daily.date===today)return false;const rnd=seedRandom(`hollow-${today}-${state.sprites.length}`);const shuffled=TASK_POOL.slice().map((t)=>({t,k:rnd()})).sort((a,b)=>a.k-b.k).map((x)=>x.t).slice(0,4);state.daily={date:today,counters:{},tasks:shuffled.map((t)=>({...t,claimed:false})),};saveState();return true;}
