var GAME_INFO={catch:{title:'Treat Catch',icon:'🍓',tag:'Reflexes',desc:'Tap falling treats. Dodge the pebbles.',g1:'#ff9a5a',g2:'#ff5e8a'},pulse:{title:'Pulse Match',icon:'🎯',tag:'Timing',desc:'Tap when the rings line up. Chase perfects.',g1:'#8b7bff',g2:'#56c8e8'},copycat:{title:'Sprite Says',icon:'🎵',tag:'Memory',desc:'Watch the pads, then repeat the pattern.',g1:'#ffd84d',g2:'#ff8a4c'},nectar:{title:'Nectar Pop',icon:'🌸',tag:'Reflexes',desc:'Tap blooming flowers. Dodge grumpy bees.',g1:'#ff8fc8',g2:'#a3e635',unlock:4},match:{title:'Moon Match',icon:'🌙',tag:'Memory',desc:'Flip moon cards and find every pair.',g1:'#8b7bff',g2:'#38bdf8',unlock:12},dig:{title:'Coin Dig',icon:'🪙',tag:'Reflexes & risk',desc:'Tap buried coins and gems. Dodge the bombs.',g1:'#ffd166',g2:'#f2a23c'},cardclash:{title:'Element Card Duel',icon:'🃏',tag:'Cards',desc:'Play elemental cards. Win rounds and fill the pantry.',g1:'#8b7bff',g2:'#38bdf8'},guardian:{title:'Guardian Duel',icon:'⚔️',tag:'Guardian bout',desc:'Tap Strike before the guardian’s resolve breaks.',g1:'#8b7bff',g2:'#ffd166'},};function gameIntroStyle(kind,info){const tag=String(info&&info.tag||'').toLowerCase();if(info&&info.sportGame)return'bounce';if(info&&info.walkGame)return'trail';if(/card|duel/.test(tag))return'fan';if(/memory/.test(tag))return'flip';if(/timing/.test(tag))return'pulse';if(/reflex/.test(tag))return'burst';return'pop';}
