Object.assign(GAME_INFO,{temple:{title:'Ember & Tide Temple',icon:'🏛️',tag:'Co-op puzzle',desc:'Switch between ember and tide sprites, cross your element, and reach both doors.',g1:'#ff8a5c',g2:'#38bdf8',},});const TEMPLE_LEVEL_ROWS=[['############','#..........#','#..........#','#..........#','#...*..o...#','#...####...#','#E.......T.#','#t..wwff.e.#','############',],['############','#..........#','#..........#','#..........#','#....=.....#','#....=.....#','#E.*.=..o.T#','#t.S.=...e.#','############',],['############','#..........#','#..........#','#..........#','#...*.=o...#','#...##=##..#','#E........T#','#t.Sww=ff.e#','############',],];const TEMPLE_LEVEL_NAMES=['Twin Doors','The Sealed Gate','Crossed Elements'];const TEMPLE_ELEMENTS={ember:{name:'Ember',icon:'🔥',color:'#ff8a5c',soft:'#ffd0b8'},tide:{name:'Tide',icon:'💧',color:'#5ad6ff',soft:'#c2f0ff'},};const TEMPLE_GEM_TOTAL=6;function templeParse(rows){const level={rows,width:rows[0].length,height:rows.length,emberStart:null,tideStart:null,doors:{},gems:[],pools:[],switchTile:null,gateTiles:[],};rows.forEach((line,row)=>{[...line].forEach((tile,col)=>{if(tile==='E')level.emberStart={col,row};else if(tile==='T')level.tideStart={col,row};else if(tile==='e')level.doors.ember={col,row};else if(tile==='t')level.doors.tide={col,row};else if(tile==='*')level.gems.push({element:'ember',col,row,got:false});else if(tile==='o')level.gems.push({element:'tide',col,row,got:false});else if(tile==='f')level.pools.push({element:'ember',col,row});else if(tile==='w')level.pools.push({element:'tide',col,row});else if(tile==='S')level.switchTile={col,row};else if(tile==='=')level.gateTiles.push({col,row});});});return level;}
