function updateHud(){levelEl.textContent=`Level ${levelIndex + 1} / ${TEMPLE_LEVEL_ROWS.length}`;gemsEl.textContent=`💎 ${gems} / ${TEMPLE_GEM_TOTAL}`;gateEl.textContent=gateOpen?'Gate open':'Gate sealed';gateEl.classList.toggle('is-open',gateOpen);activeButtons.forEach((button)=>button.classList.toggle('is-active',button.dataset.templeActive===active));shell.scoreEl.textContent=scoreNow().toLocaleString('en-US');shell.timerEl.textContent=`Level ${levelIndex + 1} / ${TEMPLE_LEVEL_ROWS.length}`;shell.timerBar.style.width=`${(levelIndex / TEMPLE_LEVEL_ROWS.length) * 100}%`;}
function placeChars(){chars.ember=templeMakeChar('ember',level.emberStart);chars.tide=templeMakeChar('tide',level.tideStart);chars.ember.atDoor=false;chars.tide.atDoor=false;}
function restartRoom(message='Back to the start.'){placeChars();keys.left=false;keys.right=false;jumpQueued=false;showBanner(message,1200);updateHud();}
function loadLevel(index){levelIndex=index;level=templeParse(TEMPLE_LEVEL_ROWS[levelIndex]);phase='playing';gateOpen=false;active='ember';keys.left=false;keys.right=false;jumpQueued=false;placeChars();resize();updateHud();showBanner(`Level ${levelIndex + 1} · ${TEMPLE_LEVEL_NAMES[levelIndex]}`,2200);}
function finishRun(){phase='result';running=false;keys.left=false;keys.right=false;shell.timerEl.textContent='Temple cleared';shell.timerBar.style.width='100%';const score=scoreNow();const blurb=falls===0?'A flawless run through the temple!':'The temple is cleared — the pantry is yours.';showGameResult(shell,{kind:'temple',score,coins:score,xp:55,blurb});}
function completeLevel(){if(phase!=='playing')return;phase='clear';completed+=1;keys.left=false;keys.right=false;updateHud();shell.timerEl.textContent='Room clear';shell.timerBar.style.width=`${(completed / TEMPLE_LEVEL_ROWS.length) * 100}%`;showBanner(`Room clear! ${gems} gems found`,1200);if(typeof Sfx!=='undefined')Sfx.win();clearTimeout(advanceTimer);advanceTimer=setTimeout(()=>{if(!running)return;if(levelIndex+1<TEMPLE_LEVEL_ROWS.length)loadLevel(levelIndex+1);else finishRun();},1150);}
function update(dt){if(phase!=='playing')return;const activeChar=chars[active];if(jumpQueued&&activeChar.onGround){activeChar.vy=-15;activeChar.onGround=false;}
jumpQueued=false;for(const element of['ember','tide']){const c=chars[element];const direction=element===active?(keys.right?1:0)-(keys.left?1:0):0;c.vx=direction*5.2;c.vy=Math.min(25,c.vy+33*dt);templeMove(c,level,gateOpen,dt);}
let hitWrongPool=false;for(const element of['ember','tide']){const c=chars[element];for(const pool of level.pools){if(pool.element!==element&&templeOverlap(c,pool.col,pool.row)){hitWrongPool=true;break;}}
if(hitWrongPool)break;}
if(hitWrongPool){falls+=1;restartRoom('Wrong element! Both sprites return to the start.');return;}
for(const gem of level.gems){if(gem.got)continue;const c=chars[gem.element];if(c&&templeOverlap(c,gem.col,gem.row)){gem.got=true;gems+=1;if(typeof Sfx!=='undefined')Sfx.chime();showBanner(`${TEMPLE_ELEMENTS[gem.element].name} gem found!`,900);updateHud();}}
if(level.switchTile&&!gateOpen){const onSwitch=['ember','tide'].some((element)=>templeOverlap(chars[element],level.switchTile.col,level.switchTile.row));if(onSwitch){gateOpen=true;switches+=1;if(typeof Sfx!=='undefined')Sfx.chime();showBanner('The sealed gate opens!',1300);updateHud();}}
for(const element of['ember','tide']){const door=level.doors[element];chars[element].atDoor=!!door&&templeOverlap(chars[element],door.col,door.row);}
if(chars.ember.atDoor&&chars.tide.atDoor)completeLevel();}
function resize(){const rect=board.getBoundingClientRect();if(!rect.width||!rect.height)return;const dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.max(1,Math.round(rect.width*dpr));canvas.height=Math.max(1,Math.round(rect.height*dpr));ctx.setTransform(dpr,0,0,dpr,0,0);const padX=8;const padTop=58;const padBottom=94;const usableW=Math.max(1,rect.width-padX*2);const usableH=Math.max(1,rect.height-padTop-padBottom);tile=Math.max(12,Math.min(usableW/level.width,usableH/level.height));offX=(rect.width-tile*level.width)/2;offY=padTop+Math.max(0,(usableH-tile*level.height)/2);}
