for(const pool of level.pools){const def=TEMPLE_ELEMENTS[pool.element];const x=pool.col*tile;const y=pool.row*tile+tile*0.26;const h=tile*0.74;const liquid=ctx.createLinearGradient(x,y,x,y+h);liquid.addColorStop(0,def.color+'cc');liquid.addColorStop(1,def.color+'55');ctx.fillStyle=liquid;ctx.beginPath();ctx.moveTo(x,y+Math.sin(time*2.2+pool.col)*1.8);ctx.quadraticCurveTo(x+tile/2,y-2+Math.sin(time*2.2+pool.col+1)*2,x+tile,y);ctx.lineTo(x+tile,y+h);ctx.lineTo(x,y+h);ctx.closePath();ctx.fill();ctx.fillStyle='rgba(255,255,255,.2)';ctx.fillRect(x+tile*0.16,y+3,tile*0.34,1);}
for(const element of['ember','tide']){const door=level.doors[element];if(!door)continue;const def=TEMPLE_ELEMENTS[element];const x=door.col*tile;const y=door.row*tile;const open=chars[element]&&chars[element].atDoor;ctx.save();if(open){const glow=ctx.createRadialGradient(x+tile/2,y+tile/2,2,x+tile/2,y+tile/2,tile);glow.addColorStop(0,def.color+'99');glow.addColorStop(1,def.color+'00');ctx.fillStyle=glow;ctx.fillRect(x-tile*0.5,y-tile*0.5,tile*2,tile*2);}
ctx.fillStyle=open?def.color+'55':'rgba(8,6,20,.55)';roundedRect(x+tile*0.08,y+tile*0.04,tile*0.84,tile*0.94,tile*0.3);ctx.fill();ctx.strokeStyle=def.color;ctx.lineWidth=open?2:1.3;ctx.stroke();ctx.font=`900 ${Math.max(11, Math.round(tile * 0.46))}px system-ui, sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle=def.soft;ctx.fillText(def.icon,x+tile/2,y+tile*0.52);ctx.restore();}
if(level.switchTile){const x=level.switchTile.col*tile;const y=level.switchTile.row*tile+tile*0.55;ctx.fillStyle=gateOpen?'#5ee0a0':'#ffd166';roundedRect(x+tile*0.14,y,tile*0.72,tile*0.28,tile*0.1);ctx.fill();ctx.strokeStyle='rgba(255,255,255,.4)';ctx.lineWidth=1;ctx.stroke();if(gateOpen){ctx.fillStyle='rgba(94,224,160,.16)';ctx.beginPath();ctx.arc(x+tile/2,y+tile*0.14,tile*0.55,0,Math.PI*2);ctx.fill();}}
for(const gem of level.gems){if(gem.got)continue;const def=TEMPLE_ELEMENTS[gem.element];const x=gem.col*tile+tile/2;const y=gem.row*tile+tile/2+Math.sin(time*2.8+gem.col)*2;const size=tile*0.2;ctx.save();ctx.shadowColor=def.color;ctx.shadowBlur=tile*0.35;ctx.fillStyle=def.color;ctx.beginPath();ctx.moveTo(x,y-size);ctx.lineTo(x+size,y);ctx.lineTo(x,y+size);ctx.lineTo(x-size,y);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='rgba(255,255,255,.85)';ctx.beginPath();ctx.moveTo(x,y-size*0.55);ctx.lineTo(x+size*0.28,y);ctx.lineTo(x,y+size*0.25);ctx.closePath();ctx.fill();ctx.restore();}
if(!gateOpen){for(const gate of level.gateTiles){const x=gate.col*tile;const y=gate.row*tile;ctx.fillStyle='rgba(139,123,255,.2)';ctx.fillRect(x+tile*0.12,y,tile*0.76,tile);ctx.fillStyle='#8b7bff';for(let bar=0;bar<3;bar+=1){ctx.fillRect(x+tile*(0.24+bar*0.22),y+2,Math.max(1,tile*0.055),tile-4);}}}else{for(const gate of level.gateTiles){ctx.fillStyle='rgba(139,123,255,.09)';ctx.fillRect(gate.col*tile+tile*0.12,gate.row*tile,tile*0.76,tile);}}
