function frame(now){if(!running)return;if(!lastFrame)lastFrame=now;const dt=Math.min(0.033,Math.max(0,(now-lastFrame)/1000));lastFrame=now;update(dt);draw(now/1000);raf=requestAnimationFrame(frame);}
function setActive(element){if(phase!=='playing'||!chars[element])return;active=element;jumpQueued=false;updateHud();}
function swapActive(){setActive(active==='ember'?'tide':'ember');}
function onKeyDown(event){if(event.key==='ArrowLeft'||event.key==='a'||event.key==='A'){keys.left=true;event.preventDefault();}else if(event.key==='ArrowRight'||event.key==='d'||event.key==='D'){keys.right=true;event.preventDefault();}else if(event.key==='ArrowUp'||event.key==='w'||event.key==='W'||event.key===' '||event.code==='Space'){jumpQueued=true;event.preventDefault();}else if(event.key==='q'||event.key==='Q'){swapActive();event.preventDefault();}}
function onKeyUp(event){if(event.key==='ArrowLeft'||event.key==='a'||event.key==='A')keys.left=false;else if(event.key==='ArrowRight'||event.key==='d'||event.key==='D')keys.right=false;}
function clearKeys(){keys.left=false;keys.right=false;}
function bindHold(selector,key){const button=board.querySelector(selector);if(!button)return;const down=(event)=>{event.preventDefault();keys[key]=true;button.classList.add('is-down');if(button.setPointerCapture){try{button.setPointerCapture(event.pointerId);}catch{}}};const up=(event)=>{if(event)event.preventDefault();keys[key]=false;button.classList.remove('is-down');};button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('pointerleave',up);}
bindHold('[data-temple-left]','left');bindHold('[data-temple-right]','right');const jumpButton=board.querySelector('[data-temple-jump]');jumpButton?.addEventListener('pointerdown',(event)=>{event.preventDefault();jumpQueued=true;jumpButton.classList.add('is-down');});jumpButton?.addEventListener('pointerup',(event)=>{event.preventDefault();jumpButton.classList.remove('is-down');});jumpButton?.addEventListener('pointercancel',()=>jumpButton.classList.remove('is-down'));board.querySelector('[data-temple-swap]')?.addEventListener('click',swapActive);board.querySelector('[data-temple-restart]')?.addEventListener('click',()=>restartRoom());activeButtons.forEach((button)=>{button.addEventListener('click',()=>setActive(button.dataset.templeActive));});canvas.addEventListener('pointerdown',(event)=>{const rect=canvas.getBoundingClientRect();const px=(event.clientX-rect.left-offX)/tile;const py=(event.clientY-rect.top-offY)/tile;for(const element of['ember','tide']){const c=chars[element];if(px>=c.x&&px<=c.x+c.w&&py>=c.y&&py<=c.y+c.h){setActive(element);break;}}});window.addEventListener('keydown',onKeyDown,{passive:false});window.addEventListener('keyup',onKeyUp);window.addEventListener('blur',clearKeys);if(typeof ResizeObserver!=='undefined'){resizeObserver=new ResizeObserver(resize);resizeObserver.observe(board);}else{window.addEventListener('resize',resize);}
