;
Object.assign(GAME_INFO,{kitchen:{title:'Hollow Kitchen',icon:'🍳',tag:'Cooking',desc:'Flip in the green band, then build the ticket.',g1:'#ffb347',g2:'#ff6b6b',},smoothie:{title:'Smoothie Smash',icon:'🥤',tag:'Jump & blend',desc:'Stomp fruit and coffee ingredients, fill the blender, then serve the order.',g1:'#7fe0a0',g2:'#56c8e8',},musicjam:{title:'Neon Beatway',icon:'🎹',tag:'Rhythm',desc:'Tap the lanes as the tiles cross the line.',g1:'#b06bff',g2:'#ff5ea8',},});function kNode(tag,cls,html){const node=document.createElement(tag);if(cls)node.className=cls;if(html!=null)node.innerHTML=html;return node;}
function kRand(min,max){return min+Math.random()*(max-min);}
function kShuffle(list){const out=list.slice();for(let i=out.length-1;i>0;i-=1){const j=Math.floor(Math.random()*(i+1));const tmp=out[i];out[i]=out[j];out[j]=tmp;}
return out;}
function kFloatText(host,text,cls){const node=kNode('span',`kf-float ${cls || ''}`,text);node.style.left=`${38 + Math.random() * 24}%`;host.appendChild(node);setTimeout(()=>node.remove(),820);}
