var CLASSIC_GAME_KEYS=['icefish','bubble','snowslide'];Object.assign(GAME_INFO,{icefish:{title:'Ice Fishing',icon:'🎣',tag:'Timing',group:'arcade',desc:'Tap Strike the moment the bobber dips. Chains pay more; early taps break the chain.',g1:'#5ad6ff',g2:'#c2f0ff',},bubble:{title:'Bubble Pop',icon:'🫧',tag:'Reflexes',group:'arcade',desc:'Pop drifting bubbles before they float away. Big ones are worth three.',g1:'#8be9ff',g2:'#b69cff',},snowslide:{title:'Snowslide Run',icon:'🏂',tag:'Runner',group:'arcade',desc:'Swap lanes to dodge the pines. Every tree you pass is a point.',g1:'#d6f6ff',g2:'#4db8d8',},});function openClassicGame(kind){if(kind==='icefish')return openIceFishGame();if(kind==='bubble')return openBubblePopGame();if(kind==='snowslide')return openSnowslideGame();return null;}
