function paint(){grid.innerHTML=cells.map((cell,index)=>{const here=player.y*PATROL_SIZE+player.x===index;const tone=cell.kind==='hazard'?'rgba(139,123,255,.24)':cell.kind==='exit'?'rgba(255,209,102,.22)':'rgba(255,255,255,.08)';return `<button type="button" data-patrol-cell="${index}" aria-label="Ice tile ${index + 1}" style="min-height:34px;border-radius:8px;border:1px solid rgba(255,255,255,.18);background:${here ? 'rgba(255,255,255,.24)' : tone};font-size:19px;line-height:1">${tileIcon(cell, index)}</button>`;}).join('');foundEl.textContent=`${found} / 3`;shell.scoreEl.textContent=Math.floor(score);}
