 cell=event.target.closest('[data-round-cell]');if(!cell||!cell.dataset.kind)return;const kind=cell.dataset.kind;clearCell(cell);if(kind==='puffle'){score+=12;rounded+=1;Sfx.coin();countEl.textContent=`${rounded} rounded up`;}else{score=Math.max(0,score-5);Sfx.error();}
