const WAVE_GAME_INFO={sortsprint:{title:'Sort Sprint',icon:'🧺',tag:'Sort & Match',desc:'Send each item to the right basket before the clock runs out.',g1:'#ffd166',g2:'#7ee787'},orbittap:{title:'Orbit Tap',icon:'🛰️',tag:'Precision Timing',desc:'Tap the moment the orbiting spark crosses the glowing gate.',g1:'#8be9ff',g2:'#c084fc'},};if(typeof GAME_INFO!=='undefined')Object.assign(GAME_INFO,WAVE_GAME_INFO);function waveCountdown(shell,seconds,onEnd){const total=seconds*1000;const startedAt=performance.now();const tick=setInterval(()=>{const left=Math.max(0,total-(performance.now()-startedAt));shell.timerEl.textContent=`${Math.ceil(left / 1000)}s`;shell.timerBar.style.width=`${Math.max(0, (left / total) * 100)}%`;if(left<=0)onEnd();},100);shell.addCleanup(()=>clearInterval(tick));return tick;}
