function filterAchievementRows(){document.querySelectorAll('[data-achievements]').forEach((fold)=>{const input=fold.querySelector('[data-ach-search]');const query=((input&&input.value)||'').trim().toLowerCase();const onlyPlayed=fold.getAttribute('data-played-only')==='1';let shown=0;fold.querySelectorAll('.ach-row').forEach((row)=>{const hit=(!query||(row.getAttribute('data-search')||'').indexOf(query)>=0)&&(!onlyPlayed||row.getAttribute('data-played')==='1');row.hidden=!hit;if(hit)shown+=1;});const empty=fold.querySelector('[data-ach-empty]');if(empty)empty.hidden=shown>0;});}
