function healthChipText(sprite){if(!sprite)return'🌡️ —';if(sprite.stage==='egg')return'🌡️ Egg';const temp=tempText(Sickness.temperature(sprite));const info=Sickness.info(sprite);return info?`${info.icon} ${temp} · Sick`:`🌡️ ${temp}`;}
