function copyColourwayText(text,label){const ok=()=>{if(typeof toast==='function')toast(`${label} — paste it into the Studio dye wheel.`,'🎨');};const fallback=()=>{try{const area=document.createElement('textarea');area.value=text;area.setAttribute('readonly','');area.style.cssText='position:fixed;top:0;left:0;opacity:0;pointer-events:none';document.body.appendChild(area);area.select();const copied=document.execCommand('copy');area.remove();if(copied)ok();else if(typeof toast==='function')toast('The browser blocked the copy.','⚠️');}catch(e){if(typeof toast==='function')toast('The browser blocked the copy.','⚠️');}};if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(ok).catch(fallback);}else{fallback();}}
