      <div data-wheel style="position:absolute;inset:0;border-radius:50%;background:conic-gradient(${wheelGradient()});border:4px solid rgba(255,255,255,.88);box-shadow:0 12px 34px rgba(0,0,0,.4)">${wheelLabels()}</div>
