function spin(paid){if(spinning)return;const res=Actions.spinWheel({paid});if(!res.ok){if(res.reason==='coins')toast(`The wheel needs ${WHEEL_PAID_COST} coins for a bonus spin.`,'🪙');else if(res.reason==='limit')toast('Both bonus spins are used. Come back tomorrow.','🎡');else toast('The free spin is already used today.','🎡');paint();return;}
spinning=true;spinBtn.disabled=true;paidBtn.disabled=true;msg.textContent=paid?'A bonus spin…':'Spinning…';const center=res.index*WHEEL_SLICE+WHEEL_SLICE/2;angle=Math.ceil(angle/360)*360+360*5+(360-center);wheel.style.transition=`transform ${WHEEL_SPIN_MS}ms cubic-bezier(.12,.72,.08,1)`;wheel.style.transform=`rotate(${angle}deg)`;Sfx.tick();settleTimer=setTimeout(()=>{spinning=false;const prize=res.prize;msg.textContent=prize.coins?`${prize.label} coins!${paid ? ` That bonus spin cost ${WHEEL_PAID_COST}.` : ' Banked straight into your wallet.'}`:paid?'The dud stop. That bonus spin did not pay this time.':'The dud stop this time. There is always tomorrow.';if(prize.coins){Sfx.coin();burstOn(wheel,['🪙','✨'],8);}else Sfx.error();paint();if(typeof App!=='undefined'&&App.refresh)App.refresh();},WHEEL_SPIN_MS+80);}
