const HOUSE_TINT_DEFAULT_STRENGTH=70;function houseTintStrength(houseId){const value=state.houseTintStrengths&&state.houseTintStrengths[houseId];const pct=Math.round(Number(value));return Number.isFinite(pct)?Math.max(0,Math.min(100,pct)):HOUSE_TINT_DEFAULT_STRENGTH;}
