const FASHION_SET_RARITY={springbloom:'common',sunflare:'uncommon',harvest:'uncommon',frostveil:'rare',rainbowfestival:'rare',galaxydream:'epic',royalblossom:'legendary',dragonfestival:'mythic',spiritmoon:'rare',crystalkingdom:'epic',springqueen:'legendary',bloomqueen:'legendary',celestialbloom:'celestial',genesis:'divine',heartlight:'celestial',creator:'creator',};const FASHION_WEATHERS=['☀️ Clear','🌧️ Rain','❄️ Snow','🌈 Rainbow','⚡ Storm','🌌 Galaxy'];const FASHION_PUFFLE_SLOTS=[{name:'Headwear',icon:'👑',words:['crown','tiara','halo','cap','hat','horn']},{name:'Neckwear',icon:'🎀',words:['collar','bow','ribbon','necklace','scarf','pendant']},{name:'Back items',icon:'🎒',words:['cape','shell','backpack']},{name:'Wings',icon:'🦋',words:['wings']},{name:'Costumes',icon:'👗',words:['dress','robe','tunic','gown','mantle']},{name:'Auras',icon:'✨',words:['aura','trail','glow']},{name:'Special',icon:'💎',words:['crystal','cosmic','creation','star','galaxy']},];const FASHION_MIX_HARMONY=80;const FASHION_SPRITE_SLOTS=[{key:'head',name:'Headwear',icon:'\u{1F451}',words:['crown','tiara','hat','hood','headband','horns','halo']},{key:'body',name:'Garment',icon:'\u{1F457}',words:['cape','tunic','dress','vest','jacket','hoodie','armor','cloak','mantle','robe','robes']},{key:'feet',name:'Footwear',icon:'\u{1F463}',words:['boots','sandals','shoes','sneakers','slippers']},{key:'extra',name:'Accessory',icon:'\u{1F392}',words:['satchel','wristbands','lantern','staff','backpack','gloves','belt','jewelry','shorts','leggings','necklace']},];function fashionWords(name){return String(name||'').toLowerCase().split(/[^a-z]+/).filter(Boolean);}
function fashionSpriteSlot(name){const words=fashionWords(name);return FASHION_SPRITE_SLOTS.find((slot)=>slot.words.some((word)=>words.includes(word)))||FASHION_SPRITE_SLOTS[FASHION_SPRITE_SLOTS.length-1];}
