function fashionToneRgb(hex){const value=String(hex||'').replace('#','');const full=value.length===3?value.split('').map((c)=>c+c).join(''):value;const num=parseInt(full,16);return Number.isFinite(num)?{r:(num>>16)&255,g:(num>>8)&255,b:num&255}:{r:177,g:140,b:255};}
