function fashionMixInfo(spritePieces=[],pufflePieces=[]){const entries=fashionMixEntries(spritePieces,pufflePieces);if(!entries.length){return{score:0,entries,sets:[],season:null,tone:'#b18cff',effects:[],palette:0,seasonScore:0,effectScore:0,pairingScore:0,spriteCount:0,puffleCount:0,harmonised:false};}
const sets=[...new Set(entries.map((entry)=>entry.set))];const rugs=entries.map((entry)=>fashionToneRgb(entry.set.tone));const average=rugs.reduce((acc,rgb)=>({r:acc.r+rgb.r/rugs.length,g:acc.g+rgb.g/rugs.length,b:acc.b+rgb.b/rugs.length}),{r:0,g:0,b:0});const spread=rugs.reduce((sum,rgb)=>sum+fashionToneDistance(rgb,average),0)/rugs.length;const palette=Math.round(35*Math.max(0,1-spread));const explicit=entries.filter((entry)=>String(entry.set.season||'')!=='Any season');const counts={};explicit.forEach((entry)=>{const key=String(entry.set.season).toLowerCase();counts[key]=(counts[key]||0)+1;});const ranked=Object.keys(counts).sort((a,b)=>counts[b]-counts[a]);const bestKey=ranked[0]||null;const bestCount=bestKey?counts[bestKey]:0;const tied=ranked.length>1&&counts[ranked[1]]===bestCount;const anyCount=entries.length-explicit.length;const seasonScore=Math.round(25*((bestCount+anyCount)/entries.length));const currentKey=typeof seasonOf==='function'?seasonOf().key:null;let seasonKey=null;if(bestKey&&!tied&&bestCount>=explicit.length/2)seasonKey=bestKey;else if(!explicit.length&&currentKey)seasonKey=currentKey;const season=seasonKey?seasonKey.charAt(0).toUpperCase()+seasonKey.slice(1):null;const effectCounts={};sets.forEach((set)=>[...new Set(set.effects)].forEach((effect)=>{effectCounts[effect]=(effectCounts[effect]||0)+1;}));const union=Object.keys(effectCounts);const shared=union.filter((effect)=>effectCounts[effect]>1);const effectScore=sets.length===1?20:10+Math.round(10*(shared.length/Math.max(1,union.length)));const effects=union.slice(0,4);const spriteCount=entries.filter((entry)=>entry.side==='sprite').length;const puffleCount=entries.length-spriteCount;const slots=new Set(entries.map((entry)=>`${entry.side}:${entry.slot.name}`));const pairingScore=(spriteCount&&puffleCount?10:0)+Math.round(10*Math.min(1,slots.size/7));const score=Math.max(0,Math.min(100,palette+seasonScore+effectScore+pairingScore));const tone='#'+[average.r,average.g,average.b].map((channel)=>Math.round(channel).toString(16).padStart(2,'0')).join('');return{score,entries,sets,season,tone,effects,palette,seasonScore,effectScore,pairingScore,spriteCount,puffleCount,harmonised:score>=FASHION_MIX_HARMONY};}
function fashionSurpriseTheme(info,currentSeason){const seasonMatch=!!(info.season&&currentSeason&&info.season.toLowerCase()===String(currentSeason).toLowerCase());return{season:info.season||'',palette:info.palette||0,seasonScore:info.seasonScore||0,score:info.score||0,collections:(info.sets||[]).length,currentSeason:seasonMatch,rank:(info.palette||0)*3+(info.seasonScore||0)*2+(info.season?6:0)+(seasonMatch?8:0),};}
function fashionSurpriseMix(opts={}){const sets=(Array.isArray(opts.sets)?opts.sets:FASHION_COLLECTIONS).filter(Boolean);const harmony=Number.isFinite(opts.harmony)?opts.harmony:FASHION_MIX_HARMONY;const currentSeason=opts.currentSeason?String(opts.currentSeason).toLowerCase():null;const random=typeof opts.random==='function'?opts.random:Math.random;if(sets.length<2)return null;const slots=[...FASHION_SPRITE_SLOTS.map((slot)=>({side:'sprite',slot})),...FASHION_PUFFLE_SLOTS.map((slot)=>({side:'puffle',slot})),];const slotOf=(side,name)=>side==='puffle'?fashionPuffleSlot(name):fashionSpriteSlot(name);const pieceFor=(set,side,slot)=>(set[side]||[]).find((name)=>slotOf(side,name).name===slot.name)||'';const keyFor=(sprite,puffle)=>`${sprite.slice().sort().join('\u0001')}\u0002${puffle.slice().sort().join('\u0001')}`;const seen=new Set();const all=[];const valid=[];const recordFor=(sprite,puffle)=>{const key=keyFor(sprite,puffle);if(seen.has(key))return null;seen.add(key);const info=fashionMixInfo(sprite,puffle);if(!info.entries.length)return null;const record={sprite:sprite.slice(),puffle:puffle.slice(),info,theme:fashionSurpriseTheme(info,currentSeason)};all.push(record);if(info.sets.length>=2&&info.score>=harmony)valid.push(record);return record;};for(let first=0;first<sets.length-1;first+=1){for(let second=first+1;second<sets.length;second+=1){const base=sets[first];const other=sets[second];const choices=slots.map(({side,slot})=>{const own=pieceFor(base,side,slot);const guest=pieceFor(other,side,slot);return{side,own,guest:guest&&guest!==own?guest:''};});const walk=(index,sprite,puffle,hasGuest)=>{if(index>=choices.length){if(hasGuest)recordFor(sprite,puffle);return;}
const{side,own,guest}=choices[index];if(own)walk(index+1,side==='sprite'?[...sprite,own]:sprite,side==='puffle'?[...puffle,own]:puffle,hasGuest);if(guest)walk(index+1,side==='sprite'?[...sprite,guest]:sprite,side==='puffle'?[...puffle,guest]:puffle,true);if(!own&&!guest)walk(index+1,sprite,puffle,hasGuest);};walk(0,[],[],false);}}
if(!valid.length){let frontier=all.slice().sort((a,b)=>b.theme.rank-a.theme.rank||b.info.score-a.info.score).slice(0,120);for(let depth=0;depth<2&&!valid.length&&frontier.length;depth+=1){const before=all.length;frontier.forEach((record)=>{const used=new Set(record.info.sets.map((set)=>set.id));slots.forEach(({side,slot})=>{const current=(side==='sprite'?record.sprite:record.puffle).find((name)=>slotOf(side,name).name===slot.name)||'';sets.forEach((set)=>{if(used.has(set.id))return;const name=pieceFor(set,side,slot);if(!name||name===current)return;const next={sprite:record.sprite.slice(),puffle:record.puffle.slice()};const target=side==='sprite'?next.sprite:next.puffle;const at=target.findIndex((piece)=>slotOf(side,piece).name===slot.name);if(at>=0)target.splice(at,1,name);else target.push(name);recordFor(next.sprite,next.puffle);});});});frontier=all.slice(before).sort((a,b)=>b.theme.rank-a.theme.rank||b.info.score-a.info.score).slice(0,160);}}
if(!valid.length)return null;valid.sort((a,b)=>b.theme.rank-a.theme.rank||b.info.palette-a.info.palette||b.info.score-a.info.score);const best=valid[0];const finalists=valid.filter((record)=>record.theme.rank>=best.theme.rank-2&&record.theme.palette>=best.theme.palette-1&&record.theme.seasonScore>=best.theme.seasonScore-1);const shortlist=finalists.length?finalists:[best];const index=Math.min(shortlist.length-1,Math.floor(Math.max(0,Math.min(0.999999,Number(random())||0))*shortlist.length));const chosen=shortlist[index];return{sprite:chosen.sprite.slice(),puffle:chosen.puffle.slice(),info:chosen.info,collections:chosen.info.sets.length,theme:{...chosen.theme,bestPalette:best.theme.palette,bestSeasonScore:best.theme.seasonScore,bestRank:best.theme.rank,},};}
function fashionMixSet(sprite){const s=sprite||(typeof activeSprite==='function'?activeSprite():null);const look=s&&s.wardrobeLook;if(!look||look.setId!=='mixed')return null;const pufflePieces=s.puffleWardrobeLook&&s.puffleWardrobeLook.setId==='mixed'?s.puffleWardrobeLook.pieces:[];const info=fashionMixInfo(look.pieces,pufflePieces);if(info.score<FASHION_MIX_HARMONY||!info.season)return null;return{id:'mixed',name:'Mixed look',icon:'\u{1F9E9}',group:'mix',mixed:true,season:info.season,tone:info.tone,effects:info.effects,sprite:Array.isArray(look.pieces)?look.pieces.slice():[],puffle:Array.isArray(pufflePieces)?pufflePieces.slice():[],score:info.score,};}
