function sptTierStyle(tier){const styles=typeof RARITY_TIER_STYLES!=='undefined'?RARITY_TIER_STYLES:{};return styles[tier.id]||{name:tier.id,icon:'⚪',color:'#C9CDD2',glow:'rgba(201,205,210,.5)'};}
