      <div class="ap-card-head">${sptPortrait(line, { slot: '5' }, `${line.mythic.name}`)}<span class="ap-family"><b>${line.icon} ${sptEsc(line.mythic.name)}</b><small>Mythic ${sptEsc(line.name)} · ${sptEsc(line.mythic.shell)}</small></span></div>
