function updateBadges(){ensureQuests();const slot=currentCheckinSlot();const claimable=[...(state.daily?.tasks||[]).map((t)=>({t,period:'daily'})),...(state.weekly?.tasks||[]).map((t)=>({t,period:'weekly'})),...(state.monthly?.tasks||[]).map((t)=>({t,period:'monthly'})),].some(({t,period})=>!t.claimed&&periodCounter(t,period)>=t.goal);const today=document.querySelector('[data-badge="today"]');if(today)today.hidden=!(!slot.claimed||claimable);const hollow=document.querySelector('[data-badge="hollow"]');if(hollow)hollow.hidden=!giftReady();const nest=document.querySelector('[data-badge="nest"]');if(nest)nest.hidden=!eggs().some((e)=>e.hatch>=100);}
function paintAppFramePalette(daily,motion){if(!daily)return;const root=document.documentElement;root.style.setProperty('--sh-frame-a',daily.a);root.style.setProperty('--sh-frame-b',daily.b);root.style.setProperty('--sh-frame-c',daily.c);root.style.setProperty('--sh-frame-intensity',String(daily.intensity==null?1:daily.intensity));if(motion)root.dataset.frameMotion=motion;}
