function ensureTypeEggRoster(){if(typeof TYPE_EGG_SPECIES==='undefined'||typeof TYPE_EGG_BASE_PRICE==='undefined')return;ELEMENT_KEYS.forEach((key)=>{if(!TYPE_EGG_BASE_PRICE[key]||TYPE_EGG_SPECIES.includes(key))return;if(key===MASTER_CHEAT_SPECIES)return;if(typeof isSecretSpecies==='function'&&isSecretSpecies(key))return;TYPE_EGG_SPECIES.push(key);});const unique=[...new Set(TYPE_EGG_SPECIES)];TYPE_EGG_SPECIES.length=0;TYPE_EGG_SPECIES.push(...unique);}
